import mechanize
from bs4 import BeautifulSoup


def task_func(url, form_id, data):
    br = mechanize.Browser()
    br.set_handle_robots(False)

    br.open(url)

    target_nr = None
    for i, form in enumerate(br.forms()):
        attrs = getattr(form, "attrs", {}) or {}
        if attrs.get("id") == form_id or attrs.get("name") == form_id:
            target_nr = i
            break

    if target_nr is None:
        raise ValueError("Form not found")

    br.select_form(nr=target_nr)

    for key, value in data.items():
        try:
            br[key] = value
        except Exception:
            try:
                if isinstance(value, (list, tuple)):
                    br.form.find_control(name=key).value = list(value)
                else:
                    br.form.find_control(name=key).value = value
            except Exception:
                pass

    response = br.submit()
    html = response.read()
    soup = BeautifulSoup(html, "html.parser")

    if soup.title and soup.title.get_text(strip=True):
        return soup.title.get_text(strip=True)
    return "No Title"
